const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.resolve(process.argv[2]);
const html=fs.readFileSync(path.join(root,'团队操作速查.html'),'utf8');
const scripts=[...html.matchAll(/<script([^>]*)>([\s\S]*?)<\/script>/g)];
const elements=new Map();
function element(){return {value:'',checked:false,textContent:'',children:[],append(...xs){this.children.push(...xs);},prepend(x){this.children.unshift(x);},replaceChildren(...xs){this.children=xs;},setAttribute(){}};}
function get(id){if(!elements.has(id))elements.set(id,element());return elements.get(id);}
get('data').textContent=scripts.find(s=>s[1].includes('application/json'))[2];
const context=vm.createContext({console,document:{getElementById:get,createElement:element,querySelectorAll:()=>[]},confirm:()=>true});
for(const s of scripts)if(!s[1].includes('application/json'))vm.runInContext(s[2],context);
const texts=el=>[el.textContent,...el.children.flatMap(texts)].join('\n');
async function importFile(name,text){await get('import').onchange({target:{files:[{name,size:Buffer.byteLength(text),text:async()=>text}],value:'test'}});}
(async()=>{
 get('query').value='报销';get('query').oninput();
 assert(texts(get('results')).includes('周宁'));assert(!texts(get('results')).includes('陈晓'));
 const updated=fs.readFileSync(path.join(root,'inputs','02-报销现行.md'),'utf8').replaceAll('周宁','李月').replaceAll('每周三','每周四');
 await importFile('02-报销现行.md',updated);
 const result=texts(get('results'));
 assert(result.includes('李月')&&result.includes('每周四'));assert(!result.includes('周宁'));
 await importFile('02-报销现行.md','');
 assert(texts(get('results')).includes('李月'));assert(get('message').textContent.includes('未导入'));
 get('query').value='年假能休几天';get('query').oninput();
 assert(texts(get('results')).includes('没有找到相关说明'));
 console.log(JSON.stringify({passed:true,checks:['initial current-only render','same-name import replaces contact and day','empty replacement rejected without losing valid update','unsupported query renders explicit no-match'],scope:'Original embedded scripts and import/render handlers with mocked DOM. Browser selection, serialization/download/reopen and layout not tested.'},null,2));
})().catch(e=>{console.error(e);process.exitCode=1;});
